<script setup>
import { bindingText, clone, issueText, originLabels, pretty, resourceFiles, updateResource } from '../assetAppsModel.js';
import { USER_FACING_ERROR } from '../../../shared/userFacingError.js';
const props = defineProps({ definition: { type: Object, required: true }, editable: Boolean, disabled: Boolean, selectable: Boolean, selectedNodes: { type: Array, default: () => [] } });
const emit = defineEmits(['update:definition', 'update:selectedNodes']);
function updateNode(index, patch) {
  const definition = clone(props.definition);
  definition.nodes[index] = { ...definition.nodes[index], ...patch };
  emit('update:definition', definition);
}
function updateCode(index, code) { updateNode(index, { code, provenance: { ...(props.definition.nodes[index].provenance || {}), type: 'modified' } }); }
function updateFile(index, path, text) { const definition = clone(props.definition); definition.nodes[index] = updateResource(definition.nodes[index], path, text); emit('update:definition', definition); }
function move(index, offset) {
  const definition = clone(props.definition), other = index + offset;
  [definition.nodes[index], definition.nodes[other]] = [definition.nodes[other], definition.nodes[index]];
  emit('update:definition', definition);
}
function select(id, checked) { emit('update:selectedNodes', checked ? [...props.selectedNodes, id] : props.selectedNodes.filter(value => value !== id)); }
</script>

<template>
  <div class="asset-definition">
    <section class="asset-definition-overview" aria-label="输入与固定规则">
      <div><h3>每次可以改变</h3><dl v-if="Object.keys(definition.inputSchema?.properties || {}).length" class="asset-definition-inputs"><template v-for="(field,key) in definition.inputSchema.properties" :key="key"><dt>{{ field.title || key }}<span v-if="definition.inputSchema.required?.includes(key)"> · 必填</span></dt><dd>{{ field.description || key }}<small v-if="Object.hasOwn(field,'default')">默认值：{{ pretty(field.default) }}</small></dd></template></dl><p v-else>尚未定义可变参数，可在创作或高级编辑中补充。</p></div>
      <div><h3>每次保持一致</h3><ul v-if="definition.rules?.length"><li v-for="(rule,index) in definition.rules" :key="index">{{ rule }}</li></ul><p v-else>尚未填写固定规则，请核对算法与数据口径。</p></div>
    </section>
    <section v-if="definition.gaps?.length" class="asset-definition-gaps" aria-label="待补内容"><h3>先补齐这些内容</h3><p>{{ USER_FACING_ERROR }}</p></section>
    <div class="asset-definition-heading"><div><span class="asset-kicker">SAVED METHOD</span><h3>一步一步，看清实际方法</h3></div><span>{{ definition.nodes?.length || 0 }} 个顺序步骤</span></div>
    <p v-if="!definition.nodes?.length" class="asset-definition-empty">描述你要保留的方法，或从一次成功任务中整理步骤。空草稿可以保存，完整交付后再验证启用。</p>
    <ol class="asset-node-list">
      <li v-for="(node,index) in definition.nodes || []" :key="node.id" class="asset-node">
        <span class="asset-node-index" aria-hidden="true">{{ String(index + 1).padStart(2,'0') }}</span>
        <div class="asset-node-body">
          <div class="asset-node-head"><div><div class="asset-node-meta"><span>{{ ({ code:'内嵌代码', tool:'Tool · 固定实现', skill:'Skill · 节点内动态执行' })[node.kind] || node.kind }}</span><span :class="'origin-' + node.provenance?.type">{{ originLabels[node.provenance?.type] || '来源待核对' }}</span></div><input v-if="editable" :value="node.title" :disabled="disabled" :aria-label="'步骤 ' + (index + 1) + ' 名称'" @input="updateNode(index,{title:$event.target.value})" /><h4 v-else>{{ node.title || node.id }}</h4></div><label v-if="selectable" class="asset-node-select"><input type="checkbox" :checked="selectedNodes.includes(node.id)" :disabled="disabled" @change="select(node.id,$event.target.checked)" />提取此步</label></div>
          <p v-if="node.provenance?.description" class="asset-node-muted">{{ node.provenance.description }}</p>
          <p v-if="node.component" class="asset-node-muted">组件：{{ node.component.name || node.component.manifest?.name || node.component.sourceIdentity || '版本快照' }}<span v-if="node.component.versionId"> · {{ node.component.versionId }}</span></p>
          <p v-if="node.provenance?.runId" class="asset-node-source">来源任务 {{ node.provenance.runId }}<span v-if="node.provenance.stepId"> · 步骤 {{ node.provenance.stepId }}</span></p>
          <dl v-if="Object.keys(node.inputBindings || {}).length" class="asset-node-bindings"><template v-for="(binding,name) in node.inputBindings" :key="name"><dt>{{ name }}</dt><dd>{{ bindingText(binding) }}</dd></template></dl><p v-else class="asset-node-muted">该步骤尚未声明输入来源。</p>
          <label v-if="editable && node.kind === 'skill'" class="asset-node-field">本节点任务<textarea :value="node.task" :disabled="disabled" rows="3" @input="updateNode(index,{task:$event.target.value,provenance:{...node.provenance,type:'modified'}})" /></label><p v-else-if="node.task" class="asset-node-task">{{ node.task }}</p>
          <details v-if="typeof node.code === 'string'" class="asset-node-file"><summary>实际代码 · run(payload)</summary><textarea v-if="editable" :value="node.code" :disabled="disabled" spellcheck="false" rows="13" :aria-label="node.id + ' 实现源码'" @input="updateCode(index,$event.target.value)" /><pre v-else>{{ node.code }}</pre></details>
          <details v-for="file in resourceFiles(node)" :key="file.path" class="asset-node-file"><summary>{{ file.path }}<small>{{ file.displayText === null ? '资源文件' : '完整内容' }}</small></summary><textarea v-if="editable && file.displayText !== null" :value="file.displayText" :disabled="disabled" rows="12" spellcheck="false" :aria-label="node.id + ' ' + file.path" @input="updateFile(index,file.path,$event.target.value)" /><pre v-else-if="file.displayText !== null">{{ file.displayText }}</pre><p v-else>以原始字节保存在版本包中，不按文本解释。<span v-if="file.size">{{ file.size }} 字节。</span></p><small v-if="file.sha256" class="asset-node-source">SHA-256 {{ file.sha256 }}</small></details>
          <details class="asset-node-delivery"><summary>交给下一步的结果要求</summary><pre>{{ pretty(node.delivery || {}) }}</pre></details>
          <div class="asset-node-bottom"><label v-if="editable"><input type="checkbox" :checked="node.checkpoint" :disabled="disabled" @change="updateNode(index,{checkpoint:$event.target.checked})" />此步完成后，由我检查再继续</label><span v-else>{{ node.checkpoint ? '完成后等待你的检查' : '交付检查通过后继续下一步' }}</span><div v-if="editable" class="asset-node-order"><button type="button" :disabled="disabled || index === 0" :aria-label="'上移步骤 ' + node.id" @click="move(index,-1)">↑ 上移</button><button type="button" :disabled="disabled || index === definition.nodes.length - 1" :aria-label="'下移步骤 ' + node.id" @click="move(index,1)">↓ 下移</button></div></div>
        </div>
      </li>
    </ol>
    <details v-if="Object.keys(definition.outputs || {}).length" class="asset-final-output"><summary>最终交付的来源</summary><dl class="asset-node-bindings"><template v-for="(binding,name) in definition.outputs" :key="name"><dt>{{ name }}</dt><dd>{{ bindingText(binding) }}</dd></template></dl></details>
    <details v-if="definition.parameterization?.length" class="asset-final-output"><summary>参数化审阅记录</summary><pre>{{ pretty(definition.parameterization) }}</pre></details>
  </div>
</template>

<style scoped>
