min-width:0;background:var(--surface)}.asset-node-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.asset-node-head>div{min-width:0;flex:1}.asset-node h4{font-size:17px;margin:11px 0 12px;font-weight:600}.asset-node-meta{display:flex;gap:8px;flex-wrap:wrap;font-size:10px;line-height:1.7;color:var(--muted)}.asset-node-meta>span{padding:2px 7px;background:var(--surface-2);border-radius:4px}.asset-node-meta>.origin-historical{color:var(--success-ink);background:var(--success-wash)}.asset-node-meta>.origin-generated,.asset-node-meta>.origin-modified{color:var(--warning-ink);background:var(--warning-wash)}.asset-node-select{font-size:11px;white-space:nowrap;color:var(--muted);display:flex;align-items:center;gap:5px}.asset-node-muted,.asset-node-task{font-size:13px;line-height:1.8;color:var(--muted);margin:9px 0}.asset-node-source{font-size:10px;color:var(--dim);line-height:1.8;overflow-wrap:anywhere}.asset-node-bindings{display:grid;grid-template-columns:minmax(70px,1fr) minmax(0,3fr);font-size:12px;gap:7px 14px;padding:12px 0;margin:8px 0;line-height:1.7}.asset-node-bindings dt{color:var(--text);overflow-wrap:anywhere}.asset-node-bindings dd{margin:0;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere}.asset-node-file,.asset-node-delivery,.asset-final-output{margin-top:12px;font-size:12px}.asset-definition summary{cursor:pointer;padding:10px 0;color:var(--build-ink);overflow-wrap:anywhere}.asset-definition summary small{color:var(--muted);margin-left:10px}.asset-definition pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:15px;border-radius:8px;font-size:12px;line-height:1.75;max-height:400px;overflow:auto;background:var(--surface-2);margin:5px 0}.asset-definition textarea,.asset-definition input:not([type=checkbox]){width:100%;min-width:0;background:var(--surface-2);border:1px solid var(--line);border-radius:8px;color:var(--text);padding:10px;font:inherit;font-size:13px;line-height:1.7;resize:vertical}.asset-node-head input{margin-top:9px}.asset-node-file textarea{font-family:Consolas,monospace;font-size:12px}.asset-node-field{display:grid;gap:8px;font-size:12px;margin:12px 0}.asset-node-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:13px;margin-top:15px;font-size:11px;color:var(--muted)}.asset-node-bottom label{display:flex;align-items:center;gap:7px}.asset-node-order{display:flex;gap:6px}.asset-node-order button{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:5px;padding:5px 7px;font-size:11px}.asset-final-output{border-top:1px solid var(--line);padding-top:7px}@media(max-width:620px){.asset-definition-overview{grid-template-columns:1fr;gap:22px}.asset-node{gap:9px}.asset-node-index{width:26px;height:26px;font-size:12px}.asset-node:not(:last-child):before{left:12px;top:28px}.asset-node-body{padding:14px}.asset-node-head{flex-wrap:wrap}.asset-node-bindings{grid-template-columns:1fr;gap:3px}.asset-node-bindings dd{margin-bottom:7px}.asset-definition-heading{align-items:start}.asset-definition-heading>span{white-space:nowrap}.asset-definition h3{font-size:15px}}
</style>
